// ---------- humanoid character: shared by bots and remote players ----------
// pos = feet. Returns spheres + capsule limbs for the ray tracer. walkPhase
// drives a leg/arm swing cycle (radians; advance by distance traveled).
export const MAT_CHAR_LIMB = 12;
export function characterRig(pos, yaw, crouch, tint, sink = 0, walkPhase = 0, moving = 0) {
  const k = crouch ? 0.74 : 1;
  const fx = Math.sin(yaw), fz = -Math.cos(yaw);   // facing
  const rx = Math.cos(yaw), rz = Math.sin(yaw);    // right
  const y = v => pos[1] + v * k - sink;
  const P = (f, r) => [pos[0] + fx * f + rx * r, pos[2] + fz * f + rz * r];
  const swing = Math.sin(walkPhase) * 0.26 * moving;
  const lift = Math.max(0, Math.sin(walkPhase)) * 0.1 * moving;
  const lift2 = Math.max(0, -Math.sin(walkPhase)) * 0.1 * moving;

  const [hx, hz] = P(0.02, 0);
  const [vx, vz] = P(0.21, 0);
  const spheres = [
    { x: hx, y: y(1.52), z: hz, r: 0.21, mat: MAT.CHAR_BODY, tint },
    { x: vx, y: y(1.54), z: vz, r: 0.105, mat: MAT.CHAR_VISOR, tint },
    { x: pos[0], y: y(0.82), z: pos[2], r: 0.23, mat: MAT.DARKMETAL, tint }, // hips
  ];
  const capsules = [];
  const cap = (a, b, r, mat) => capsules.push({
    ax: a[0], ay: a[1], az: a[2], bx: b[0], by: b[1], bz: b[2], r, mat, tint,
  });
  // torso: shoulders to waist
  cap([pos[0], y(1.32), pos[2]], [pos[0], y(0.92), pos[2]], 0.26, MAT.CHAR_CLOTH);
  // legs: hip sockets to feet, swinging fore/aft when moving
  const [l1x, l1z] = P(0, -0.13), [l2x, l2z] = P(0, 0.13);
  const [f1x, f1z] = P(swing, -0.14), [f2x, f2z] = P(-swing, 0.14);
  cap([l1x, y(0.74), l1z], [f1x, pos[1] + 0.09 + lift * k - sink, f1z], 0.095, MAT_CHAR_LIMB);
  cap([l2x, y(0.74), l2z], [f2x, pos[1] + 0.09 + lift2 * k - sink, f2z], 0.095, MAT_CHAR_LIMB);
  // arms: shoulders outward+down; off-hand swings opposite the near leg,
  // gun arm always raised toward facing
  const [s1x, s1z] = P(0.02, -0.30), [s2x, s2z] = P(0.02, 0.30);
  const [h1x, h1z] = P(-swing * 0.7 + 0.06, -0.32);
  cap([s1x, y(1.26), s1z], [h1x, y(0.78), h1z], 0.075, MAT_CHAR_LIMB);
  const [g1x, g1z] = P(0.38, 0.24);
  cap([s2x, y(1.26), s2z], [g1x, y(1.06), g1z], 0.075, MAT_CHAR_LIMB);
  // weapon: short capsule from gun hand pointing forward
  const [m1x, m1z] = P(0.62, 0.18);
  cap([g1x, y(1.07), g1z], [m1x, y(1.1), m1z], 0.05, MAT.DARKMETAL);
  return { spheres, capsules };
}
